/**
 * @zakkster/lite-leak kernel: child-process-orphan
 *
 * Detects child processes spawned inside an owner that outlive it without being
 * killed -- zombie processes.
 *
 * A spawned process is held by the OS, not by your JavaScript. Dropping the
 * `ChildProcess` reference does nothing: the process keeps running, holding its
 * own file descriptors, sockets and memory, and (for fork) an open IPC channel.
 * A worker spawned on mount and forgotten on unmount leaks a live process per
 * mount, which exhausts the process table and file descriptors long before it
 * shows up as JS heap growth -- because it never touches the JS heap at all.
 *
 * Same shape as socket-orphan and worker-orphan: patch the process-creating
 * functions, wire `onCleanup(() => child.kill())` when the process is spawned
 * inside an effect/computed body, and warn at spawn outside any owner. The live
 * registry holds WeakRefs, so the kernel never keeps a `ChildProcess` object
 * alive on its own.
 *
 * audit() reports by process state, not bookkeeping: a process that has already
 * exited (by code or signal) is not a leak, so only one still running --
 * `exitCode === null && signalCode === null` -- counts.
 *
 * The `child_process` module is REQUIRED, not defaulted: there is no global for
 * it, and a silent default would install a kernel that patches nothing. Pass it:
 *
 *   import * as childProcess from 'node:child_process';
 *   createChildProcessOrphanKernel({ childProcess });
 *
 * A caller that destructured `import { spawn } from 'node:child_process'` before
 * install captured its own binding and is not caught -- the same early-binding
 * caveat every constructor/factory kernel carries. Code that calls
 * `childProcess.spawn(...)` on the patched module object is caught.
 *
 * Patch surfaces: 'spawn', 'fork', 'exec', 'execFile'.
 *
 * In-house consumer: `@zakkster/lite-worker` (its Node subprocess path).
 *
 * Copyright (c) 2026 Zahary Shinikchiev <shinikchiev@yahoo.com>
 * MIT License
 */

import { getOwner, onCleanup, nodeId } from '@zakkster/lite-signal';
import { _claimPatchSurface, _releasePatchSurface, _restoreIfOurs } from '../Leak.js';

const KIND = 'child-process-orphan';
const EMPTY_OPTIONS = Object.freeze(Object.create(null));

const SPAWN_SURFACES = ['spawn', 'fork', 'exec', 'execFile'];

/**
 * Create the child-process-orphan kernel.
 *
 * @param {object} options
 * @param {object} options.childProcess
 *   The `child_process` module (or any object exposing spawn/fork/exec/
 *   execFile). Required.
 * @param {boolean} [options.warnOnNoOwner=true]
 *   Warn when a process is spawned outside any owner. On by default: a spawn is
 *   a deliberate, heavyweight resource acquisition, not runtime noise.
 * @param {boolean} [options.captureStacks=false]
 * @param {number} [options.priority=0]
 */
export function createChildProcessOrphanKernel(options) {
  const opts = options || EMPTY_OPTIONS;
  const target = opts.childProcess;
  if (target === null || typeof target !== 'object') {
    throw new TypeError(
      'createChildProcessOrphanKernel: options.childProcess is required (import ' +
      '* as childProcess from "node:child_process")'
    );
  }
  const warnOnNoOwner = opts.warnOnNoOwner !== false;   // opt-OUT (default true)
  const captureStacks = opts.captureStacks === true;
  const priority = typeof opts.priority === 'number' ? opts.priority : 0;

  let ctx = null;
  let originals = null;
  let ours = null;
  let claimed = null;

  const live = new Set();                 // Set<WeakRef<ChildProcess>>
  const states = new WeakMap();           // ChildProcess -> state

  /** @private A process is a leak only while it is still running. */
  function isRunning(child) {
    return child.exitCode === null && child.signalCode === null;
  }

  /** @private */
  function makePatched(orig, fnName) {
    return function patchedSpawn() {
      const child = orig.apply(this, arguments);
      if (ctx === null) return child;
      // exec/execFile can be called in ways that do not return a ChildProcess in
      // exotic shims; guard so we never track a non-process.
      if (child === null || typeof child !== 'object') return child;

      const ownerHandle = getOwner();
      const origin = captureStacks ? new Error().stack : null;
      const state = {
        ownerHandle: ownerHandle,
        origin: origin,
        via: fnName,
        reaped: false,
      };
      states.set(child, state);
      live.add(new WeakRef(child));

      // Track for the FR-refine path. Tag carries only primitives; the child is
      // already retained by the OS binding, so this adds no new retention.
      ctx.track(child, function () {}, {
        kind: 'child-process',
        via: fnName,
        origin: origin,
      }, { audit: false });

      if (ownerHandle !== undefined) {
        onCleanup(function () {
          if (ctx === null || originals === null) return;
          const s = states.get(child);
          if (s === undefined || s.reaped) return;
          // Nothing to kill (already exited, or no kill method): handled.
          if (typeof child.kill !== 'function' || !isRunning(child)) {
            s.reaped = true;
            return;
          }
          // kill() returns true when the signal was delivered. If it reports
          // failure (a broken or overridden kill), keep the record: the owner is
          // now disposed and audit will report owner-disposed-process-live -- a
          // leak the auto-kill failed to stop. A delivered signal is handled.
          let signalled = false;
          try { signalled = child.kill() !== false; } catch (_e) { signalled = true; }
          if (signalled) s.reaped = true;
        });
      } else if (warnOnNoOwner) {
        ctx.emitWarning({
          kind: KIND,
          reason: 'no-owner-spawn',
          via: fnName,
          origin: origin,
        });
      }
      return child;
    };
  }

  const kernel = {
    name: 'child-process-orphan',
    patchSurfaces: SPAWN_SURFACES.slice(),
    priority: priority,

    install(kernelCtx) {
      ctx = kernelCtx;
      originals = {};
      ours = {};
      claimed = [];
      let contested = null;

      for (const name of SPAWN_SURFACES) {
        const orig = target[name];
        if (typeof orig !== 'function') continue;
        if (_claimPatchSurface(target, name)) claimed.push(name);
        else { if (contested === null) contested = []; contested.push(name); }
        originals[name] = orig;
        ours[name] = makePatched(orig, name);
        target[name] = ours[name];
      }

      if (contested !== null) {
        ctx.emitFinding({
          kind: KIND,
          reason: 'patch-double-install',
          surfaces: contested,
          detail: 'child_process already patched by another lite-leak kernel instance; ' +
            'spawned processes would be counted twice',
        });
      }
    },

    uninstall() {
      if (originals === null) return;
      let clobbered = null;
      for (const name of SPAWN_SURFACES) {
        if (typeof originals[name] !== 'function') continue;
        if (!_restoreIfOurs(target, name, ours[name], originals[name])) {
          if (clobbered === null) clobbered = [];
          clobbered.push(name);
        }
      }
      if (clobbered !== null && ctx !== null) {
        ctx.emitFinding({
          kind: KIND,
          reason: 'patch-layered',
          surfaces: clobbered,
          detail: 'another wrapper was installed over these after this kernel; left in place',
        });
      }
      if (claimed !== null) {
        for (const name of claimed) _releasePatchSurface(target, name);
        claimed = null;
      }
      ours = null;
      live.clear();
      ctx = null;
      if (clobbered === null) originals = null;
    },

    refine(report, leakRecord) {
      const tag = leakRecord.tag;
      if (tag === null || typeof tag !== 'object') return null;
      if (tag.kind !== 'child-process') return null;
      return {
        tag: report.tag,
        ownerPath: report.ownerPath,
        origin: report.origin,
        kind: KIND,
        collectedAt: report.collectedAt,
        via: tag.via,
      };
    },

    audit() {
      if (ctx === null) return [];
      const findings = [];
      let dead = null;

      for (const ref of live) {
        const child = ref.deref();
        if (child === undefined) {
          if (dead === null) dead = [];
          dead.push(ref);
          continue;
        }
        const state = states.get(child);
        if (state === undefined || state.reaped) continue;

        // A process that has already exited is not a leak.
        if (!isRunning(child)) continue;

        if (state.ownerHandle !== undefined && state.ownerHandle !== null) {
          if (nodeId(state.ownerHandle) === undefined) {
            findings.push({
              kind: KIND,
              reason: 'owner-disposed-process-live',
              via: state.via,
              origin: state.origin,
            });
          }
        }
      }

      if (dead !== null) {
        for (let i = 0; i < dead.length; i++) live.delete(dead[i]);
      }
      return findings;
    },

    /** Live tracked processes still running and not yet reaped. */
    count: function () {
      let n = 0;
      for (const ref of live) {
        const child = ref.deref();
        if (child === undefined) continue;
        const state = states.get(child);
        if (state === undefined || state.reaped) continue;
        if (isRunning(child)) n++;
      }
      return n;
    },

    advise(finding) {
      if (finding === null || finding.kind !== KIND) return null;
      switch (finding.reason) {
        case 'owner-disposed-process-live':
          return 'A child process spawned via ' + finding.via + '() inside an owner is ' +
            'still running after that owner was disposed. The OS keeps it alive -- with its ' +
            'file descriptors, sockets and (for fork) IPC channel -- until it exits or is ' +
            'killed. Spawn it inside an effect() so onCleanup kills it on disposal, or call ' +
            'child.kill() in your own teardown.';
        case 'no-owner-spawn':
          return 'A child process was spawned via ' + finding.via + '() outside any owner, ' +
            'so nothing will kill it on teardown. If it is a long-lived daemon this is fine; ' +
            'if it is scoped work, spawn it inside an effect() so it is killed automatically.';
        case 'patch-double-install':
          return 'child_process is patched by two kernel instances at once, so spawned ' +
            'processes are counted twice. Register child-process-orphan on a single tracker.';
        case 'patch-layered':
          return 'Another library wrapped child_process after this kernel; its wrapper was ' +
            'left in place. Uninstall in reverse order of installation.';
        default:
          return null;
      }
    },
  };

  return kernel;
}
